 [-0.3, 3.950345153908895, 2.544507129230749]], "Canopy_actuator_Left_piston": [[-0.3, 3.3949421589032527, 2.3318919202051513], [-0.3, 4.03, 2.575]], "Canopy_actuator_Right_barrel": [[0.3, 3.39, 2.33], [0.3, 3.950345153908895, 2.544507129230749]], "Canopy_actuator_Right_piston": [[0.3, 3.3949421589032527, 2.3318919202051513], [0.3, 4.03, 2.575]], "Nose_gear_brace_upper": [[0.13, 5.05, 1.5], [0.13, 5.112776545029008, 1.2425430028252855]], "Nose_gear_brace_lower": [[0.13, 5.112776545029008, 1.2425430028252855], [0.13, 5.3, 1.0550000000000002]], "Nose_gear_actuator_barrel": [[-0.15, 5.54, 1.59], [-0.15, 5.338160880840471, 1.3040612478573337]], "Nose_gear_actuator_piston": [[-0.15, 5.484538623231569, 1.5114297162447237], [-0.15, 5.3, 1.25]], "Main_gear_Left_brace_upper": [[-1.92, -0.95, 1.525], [-1.92, -0.8236429586203616, 1.1454820187477484]], "Main_gear_Left_brace_lower": [[-1.92, -0.8236429586203616, 1.1454820187477484], [-1.92, -1.2, 1.01]], "Main_gear_Left_actuator_barrel": [[-1.96, -2.75, 1.3699999999999999], [-1.96, -1.951498381269825, 1.3210595782068602]], "Main_gear_Left_actuator_piston": [[-1.96, -2.098314321071447, 1.330057974517282], [-1.96, -1.2, 1.275]], "Main_gear_Right_brace_upper": [[1.92, -0.95, 1.525], [1.92, -0.8236429586203616, 1.1454820187477484]], "Main_gear_Right_brace_lower": [[1.92, -0.8236429586203616, 1.1454820187477484], [1.92, -1.2, 1.01]], "Main_gear_Right_actuator_barrel": [[1.96, -2.75, 1.3699999999999999], [1.96, -1.951498381269825, 1.3210595782068602]], "Main_gear_Right_actuator_piston": [[1.96, -2.098314321071447, 1.330057974517282], [1.96, -1.2, 1.275]], "Nose_gear_torque_link_upper": [[0.075, 5.3, 0.925], [0.12, 5.37, 0.675]], "Nose_gear_torque_link_lower": [[0.12, 5.37, 0.675], [0.075, 5.3, 0.43500000000000005]], "Main_gear_Left_torque_link_upper": [[-1.875, -1.2, 1.02], [-1.92, -1.13, 0.77]], "Main_gear_Left_torque_link_lower": [[-1.92, -1.13, 0.77], [-1.875, -1.2, 0.53]], "Main_gear_Right_torque_link_upper": [[1.875, -1.2, 1.02], [1.92, -1.13, 0.77]], "Main_gear_Right_torque_link_lower": [[1.92, -1.13, 0.77], [1.875, -1.2, 0.53]]}};
const refs = {"Canopy": "#o1.13", "Nose_gear": "#o1.330.1", "Nose_gear_torque_link_upper": "#o1.330.1.4", "Nose_gear_torque_link_lower": "#o1.330.1.5", "Main_gear_Left": "#o1.330.2", "Main_gear_Left_torque_link_upper": "#o1.330.2.6", "Main_gear_Left_torque_link_lower": "#o1.330.2.7", "Main_gear_Left_swivel": "#o1.330.2.10", "Main_gear_Right": "#o1.330.3", "Main_gear_Right_torque_link_upper": "#o1.330.3.6", "Main_gear_Right_torque_link_lower": "#o1.330.3.7", "Main_gear_Right_swivel": "#o1.330.3.10", "Nose_door_Left": "#o1.330.4", "Nose_door_Right": "#o1.330.5", "Main_door_Left_Left": "#o1.330.6", "Main_door_Left_Right": "#o1.330.7", "Main_door_Right_Left": "#o1.330.8", "Main_door_Right_Right": "#o1.330.9", "Canopy_actuator_Left_barrel": "#o1.330.10", "Canopy_actuator_Left_piston": "#o1.330.11", "Canopy_actuator_Right_barrel": "#o1.330.12", "Canopy_actuator_Right_piston": "#o1.330.13", "Nose_gear_brace_upper": "#o1.330.14", "Nose_gear_brace_lower": "#o1.330.15", "Nose_gear_actuator_barrel": "#o1.330.16", "Nose_gear_actuator_piston": "#o1.330.17", "Main_gear_Left_brace_upper": "#o1.330.18", "Main_gear_Left_brace_lower": "#o1.330.19", "Main_gear_Left_actuator_barrel": "#o1.330.20", "Main_gear_Left_actuator_piston": "#o1.330.21", "Main_gear_Right_brace_upper": "#o1.330.22", "Main_gear_Right_brace_lower": "#o1.330.23", "Main_gear_Right_actuator_barrel": "#o1.330.24", "Main_gear_Right_actuator_piston": "#o1.330.25"};
const smooth = (a,b,t) => { const x=Math.max(0,Math.min(1,(t-a)/(b-a))); return x*x*(3-2*x); };
const add = (a,b) => a.map((v,i)=>v+b[i]);
const sub = (a,b) => a.map((v,i)=>v-b[i]);
const mul = (a,s) => a.map(v=>v*s);
const norm = a => Math.hypot(...a);
const rotate = (p,o,degrees) => {
  const [x,y,z]=sub(p,o), t=degrees*Math.PI/180, c=Math.cos(t),s=Math.sin(t);
  return add([x,y*c-z*s,y*s+z*c],o);
};
const swing = (m,name,axis,angle,point) => m.get(refs[name]).rotate(axis,angle,mul(point,1000));
function segment(m,name,a,b) {
  const [ra,rb]=data.segments[name], u=sub(rb,ra),v=sub(b,a);
  const cross=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]];
  const dot=u.reduce((sum,n,i)=>sum+n*v[i],0)/(norm(u)*norm(v));
  const part=m.get(refs[name]);
  if(norm(cross)>1e-10) part.rotate(mul(cross,1/norm(cross)),Math.acos(Math.max(-1,Math.min(1,dot)))*180/Math.PI,mul(ra,1000));
  part.translate(mul(sub(a,ra),1000));
}
function ram(m,name,a,b,barrel,rod) {
  const direction=mul(sub(b,a),1/norm(sub(b,a)));
  segment(m,name+'_barrel',a,add(a,mul(direction,barrel)));
  segment(m,name+'_piston',sub(b,mul(direction,rod)),b);
}
function pose(m,phase,canopy) {
  const angle=smooth(0,1,canopy)*data.canopy.angle;
  swing(m,data.canopy.name,data.canopy.axis,angle,data.canopy.point);
  for(const [side,label] of [[-1,'Left'],[1,'Right']])
    ram(m,'Canopy_actuator_'+label,[side*.30,3.39,2.33],rotate([side*.30,4.03,2.575],data.canopy.point,angle),.60,.68);
  for(const door of data.doors)
    swing(m,door.name,door.axis,-smooth(.90,1,phase)*door.open_angle,door.point);
  for(const leg of data.legs) {
    const angle=smooth(leg.start,leg.end,phase)*leg.angle;
    if(leg.swivel) swing(m,leg.swivel.name,leg.swivel.axis,
      smooth(.30,.75,phase)*leg.swivel.angle,leg.swivel.point);
    swing(m,leg.name,leg.axis,angle,leg.point);
    const a=data.segments[leg.name+'_brace_upper'][0],
      b=rotate(data.segments[leg.name+'_brace_lower'][1],leg.point,angle);
    const d=sub(b,a),l=norm(d),h=Math.sqrt(Math.max(0,leg.brace_length**2-l*l/4))*(leg.brace_branch??1);
    const elbow=add(mul(add(a,b),.5),[0,-d[2]*h/l,d[1]*h/l]);
    segment(m,leg.name+'_brace_upper',a,elbow); segment(m,leg.name+'_brace_lower',elbow,b);
    const barrel=data.segments[leg.name+'_actuator_barrel'], rod=data.segments[leg.name+'_actuator_piston'];
    ram(m,leg.name+'_actuator',barrel[0],rotate(rod[1],leg.point,angle),
        norm(sub(barrel[1],barrel[0])),norm(sub(rod[1],rod[0])));
  }
}
export const clips = {
