  gear: { label: 'Gear · doors / retract / close', duration: 12.6, loop: true,
    update(t,m) { const p=t<4.8?t/4.8:t<6.3?1:t<11.1?1-(t-6.3)/4.8:0; pose(m,p,0); } },
};
